"use client";

import { CARD_FRAME as SHARED_CARD_FRAME } from "@/lib/card-frame";
import { cn } from "@/lib/utils";
import {
  DEFAULT_BARS,
  barTotal,
  formatBarValue,
  shouldShowTotal,
  summarizeBarChart,
  topBar,
} from "@/features/bar-chart/bar-chart-schema";
import type { BarChartData } from "@/features/bar-chart/bar-chart-schema";

export type BarChartCardState = "streaming" | "loading" | "ready" | "error";

export interface BarChartCardProperties {
  readonly state: BarChartCardState;
  /**
  The topic from the tool input, shown before the data arrives.
  */
  readonly topic?: string;
  /**
  How many bars were asked for, so the skeleton holds the ready card's height.
  */
  readonly limit?: number;
  readonly data?: BarChartData;
  readonly error?: string;
  /**
  Shows when the figures were looked up. Turn it off for saved data, where the time is the save date, not the reader's now.
  */
  readonly showAsOf?: boolean;
  readonly className?: string;
}

const CARD_FRAME = `${SHARED_CARD_FRAME} w-full max-w-md`;

const AS_OF_FORMAT = new Intl.DateTimeFormat("en-US", {
  day: "numeric",
  month: "short",
  // Fixed, so the server render and the browser agree on the date.
  timeZone: "UTC",
  year: "numeric",
});

/**
The narrowest a bar gets, in percent of its track, so a tiny value still shows a sliver.
*/
const MIN_BAR_PERCENT = 1;

function formatAsOf(time: number) {
  return AS_OF_FORMAT.format(time);
}

function titleCase(value: string) {
  return value
    .trim()
    .split(/\s+/u)
    .map((word) => (word ? word.charAt(0).toUpperCase() + word.slice(1) : word))
    .join(" ");
}

function barPercent(value: number, largest: number) {
  return largest
    ? Math.max((Math.abs(value) / largest) * 100, MIN_BAR_PERCENT)
    : MIN_BAR_PERCENT;
}

const SHARE_FORMAT = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 0,
  style: "percent",
});

/**
How long each bar waits after the one above it before growing in, so the chart draws top to bottom.
*/
const BAR_STAGGER_MS = 55;

/**
Faint rules at each quarter of the largest bar, drawn behind every track so they read as one set of columns down the chart.
*/
const GRIDLINES =
  "bg-[image:repeating-linear-gradient(to_right,var(--border)_0_1px,transparent_1px_25%)]";

/**
Print-style diagonal hatching for every bar but the leader, which stays solid. Hovering a row fills its bar in.
*/
const HATCH =
  "bg-[image:repeating-linear-gradient(-45deg,currentColor_0_1.5px,transparent_1.5px_4.5px)] group-hover/row:bg-none group-hover/row:bg-current";

function barTone(value: number, isTop: boolean) {
  if (value < 0) {
    return cn("text-red-500 dark:text-red-400", isTop ? "bg-current" : HATCH);
  }
  return isTop
    ? "bg-current text-sky-600 dark:text-sky-400"
    : cn("text-sky-500/80 dark:text-sky-400/70", HATCH);
}

/**
Whether the bars run biggest first, so numbering them as ranks is honest. Categories with their own order (months, age bands) don't get numbers.
*/
function isRanked(data: BarChartData) {
  return data.bars.every(
    (bar, index) => index === 0 || bar.value <= data.bars[index - 1].value
  );
}

function formatRank(index: number) {
  return String(index + 1).padStart(2, "0");
}

/**
The total of a parts-of-whole chart. Any other chart has no headline: its largest value already leads the rows.
*/
const Headline = ({ data }: { readonly data: BarChartData }) => {
  if (!shouldShowTotal(data)) {
    return null;
  }
  return (
    <div className="flex h-9 items-baseline gap-2.5">
      <p className="font-mono text-3xl font-semibold tracking-tighter tabular-nums">
        {formatBarValue(barTotal(data), data.scale)}
      </p>
      <p className="text-muted-foreground text-sm">
        total across {data.bars.length}
      </p>
    </div>
  );
};

const BarRows = ({ data }: { readonly data: BarChartData }) => {
  const largest = Math.max(...data.bars.map((bar) => Math.abs(bar.value)));
  const top = topBar(data);
  const total = shouldShowTotal(data) ? barTotal(data) : 0;
  const ranked = isRanked(data);
  return (
    // One grid for every row, so all the tracks share a width however wide
    // each row's value is.
    <ol
      className={cn(
        "group/bars grid gap-x-2",
        ranked &&
          total &&
          "grid-cols-[1.25rem_fit-content(8rem)_1fr_auto_2rem]",
        ranked && !total && "grid-cols-[1.25rem_fit-content(8rem)_1fr_auto]",
        !ranked && total && "grid-cols-[fit-content(8.5rem)_1fr_auto_2rem]",
        !(ranked || total) && "grid-cols-[fit-content(8.5rem)_1fr_auto]"
      )}
    >
      {data.bars.map((bar, index) => {
        const isTop = bar === top;
        return (
          <li
            key={bar.name}
            className="group/row hover:bg-muted/70 col-span-full -mx-1.5 grid h-6 grid-cols-subgrid items-center rounded-sm px-1.5 text-xs transition-[opacity,background-color] duration-200 group-hover/bars:opacity-40 hover:opacity-100"
          >
            {ranked ? (
              <span className="text-muted-foreground/70 font-mono tabular-nums">
                {formatRank(index)}
              </span>
            ) : null}
            <span className={cn("truncate", isTop && "font-semibold")}>
              {bar.name}
            </span>
            <span
              aria-hidden
              className={cn(
                "border-foreground/25 relative flex h-full items-center overflow-hidden border-l",
                GRIDLINES
              )}
            >
              <span
                className={cn(
                  "animate-in slide-in-from-left-full fill-mode-both block h-3 rounded-r-[2px] duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:animate-none",
                  barTone(bar.value, isTop)
                )}
                style={{
                  animationDelay: `${index * BAR_STAGGER_MS}ms`,
                  width: `${barPercent(bar.value, largest)}%`,
                }}
              />
            </span>
            <span
              className={cn(
                "text-right font-mono font-medium tabular-nums",
                isTop ? "text-foreground" : "text-muted-foreground"
              )}
            >
              {formatBarValue(bar.value, data.scale)}
            </span>
            {total ? (
              <span className="text-muted-foreground/70 text-right font-mono text-xs tabular-nums">
                {SHARE_FORMAT.format(bar.value / total)}
              </span>
            ) : null}
          </li>
        );
      })}
    </ol>
  );
};

const BarChartReady = ({
  data,
  showAsOf,
}: {
  readonly data: BarChartData;
  readonly showAsOf: boolean;
}) => (
  <div className="flex flex-col gap-3">
    <header className="flex h-5 min-w-0 items-center">
      <p className="truncate text-sm font-semibold">{titleCase(data.topic)}</p>
    </header>

    <Headline data={data} />

    <BarRows data={data} />

    <footer className="flex items-center justify-between gap-2">
      <p className="text-muted-foreground min-w-0 truncate text-xs">
        {data.label}
      </p>
      {showAsOf ? (
        <p className="text-muted-foreground shrink-0 text-xs">
          As of {formatAsOf(data.asOf)}
        </p>
      ) : null}
    </footer>
  </div>
);

const BarChartError = ({
  topic,
  message = "The figures service didn't respond. Try again in a moment.",
}: {
  readonly topic?: string;
  readonly message?: string;
}) => (
  <div role="alert" className="flex flex-col gap-1">
    <p className="text-sm font-semibold">
      {topic
        ? `Couldn't load a chart for ${titleCase(topic)}`
        : "Couldn't load the bar chart"}
    </p>
    <p className="text-muted-foreground text-xs">{message}</p>
  </div>
);

/** The card while its data is on the way: the same frame and rows as the
 *  ready card, so nothing moves when the figures land. Shows the topic as
 *  soon as it's known (with "…" while the model is still writing it). */
export const BarChartCardSkeleton = ({
  topic,
  rows = DEFAULT_BARS,
  streaming = false,
  className,
}: {
  readonly topic?: string;
  readonly rows?: number;
  readonly streaming?: boolean;
  readonly className?: string;
}) => (
  <output className={cn(CARD_FRAME, "flex flex-col gap-3", className)}>
    <span className="sr-only">
      {topic ? `Loading a chart for ${topic}` : "Loading a bar chart"}
    </span>
    <div aria-hidden className="flex h-5 items-center">
      {topic ? (
        <p className="truncate text-sm font-semibold">
          {titleCase(topic)}
          {streaming ? <span className="text-muted-foreground">…</span> : null}
        </p>
      ) : (
        <div className="bg-muted h-3.5 w-24 animate-pulse rounded" />
      )}
    </div>
    <div aria-hidden className="flex flex-col">
      {Array.from({ length: rows }, (_, index) => (
        <div
          // The rows are identical placeholders with nothing else to key on.

          key={index}
          className="grid h-6 grid-cols-[8.5rem_1fr] items-center gap-2"
        >
          <div className="bg-muted h-3 w-16 animate-pulse rounded" />
          <div
            className="bg-muted h-3 animate-pulse rounded-r-[2px]"
            style={{ width: `${100 - (index * 60) / rows}%` }}
          />
        </div>
      ))}
    </div>
    <div aria-hidden className="flex h-4 items-center">
      <div className="bg-muted h-3 w-20 animate-pulse rounded" />
    </div>
  </output>
);

export const BarChartCard = ({
  state,
  topic,
  limit,
  data,
  error,
  showAsOf = true,
  className,
}: BarChartCardProperties) => {
  if (state === "error") {
    return (
      <div className={cn(CARD_FRAME, className)}>
        <BarChartError topic={topic} message={error} />
      </div>
    );
  }
  if (state !== "ready" || !data) {
    return (
      <BarChartCardSkeleton
        topic={topic}
        rows={limit}
        streaming={state === "streaming"}
        className={className}
      />
    );
  }
  return (
    <section
      aria-label={summarizeBarChart(data)}
      className={cn(CARD_FRAME, className)}
    >
      <BarChartReady data={data} showAsOf={showAsOf} />
    </section>
  );
};

"use client";

import { useEffect, useState } from "react";
import { BarChartCard } from "@/features/bar-chart/components/bar-chart-card";
import { loadBarChart } from "@/features/bar-chart/bar-chart-requests";
import { barLimit } from "@/features/bar-chart/bar-chart-schema";
import type { BarChartData } from "@/features/bar-chart/bar-chart-schema";

/**
What came back for one request. A result for different props reads as still loading, so a new topic never flashes the old chart.
*/
type Result =
  | { key: string; status: "ready"; data: BarChartData }
  | { key: string; status: "error"; message: string };

export const LiveBarChartCard = ({
  topic,
  limit,
  streaming = false,
}: {
  readonly topic?: string;
  /**
  How many bars the model asked for; clamped to what the card can draw.
  */
  readonly limit?: number;
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
}) => {
  const [result, setResult] = useState<Result | null>(null);
  const bars = barLimit(limit);
  const requestKey = [topic, bars].join("|");

  useEffect(() => {
    let isCancelled = false;
    const run = async (wanted: string) => {
      let next: Result;
      try {
        next = {
          data: await loadBarChart(wanted, bars),
          key: requestKey,
          status: "ready",
        };
      } catch (error) {
        next = {
          key: requestKey,
          message: Error.isError(error) ? error.message : "Bar chart failed.",
          status: "error",
        };
      }
      if (!isCancelled) {
        setResult(next);
      }
    };
    if (!streaming && topic) {
      run(topic);
    }
    return () => {
      isCancelled = true;
    };
  }, [topic, bars, requestKey, streaming]);

  if (streaming || !topic) {
    return <BarChartCard state="streaming" topic={topic} limit={bars} />;
  }
  const current = result?.key === requestKey ? result : null;
  if (current?.status === "ready") {
    return <BarChartCard state="ready" data={current.data} />;
  }
  return current?.status === "error" ? (
    <BarChartCard state="error" topic={topic} error={current.message} />
  ) : (
    <BarChartCard state="loading" topic={topic} limit={bars} />
  );
};

import { z } from "zod";
import { MAX_BARS, MIN_BARS } from "@/features/bar-chart/bar-chart-schema";

export const barChartCatalogEntry = {
  description: `A live bar chart for questions that compare one number across categories at one point in time: countries, states, companies, teams, energy sources, age groups ("GDP by country", "most populous US states", "US electricity by source", "top 5 car makers by sales"). The model writes a free-text topic from the user's ask; the card researches the web and draws one bar per category. Never invent the numbers — the card fetches them. Not for how one number changes over the years: that's AreaChartCard. Not for disputed historical estimates (war deaths by country): answer those with webSearch, which can give ranges.`,
  props: z.object({
    limit: z
      .number()
      .int()
      .nullable()
      .describe(
        `How many bars, ${MIN_BARS}–${MAX_BARS}: the number the user asks for ("top 5"), or null for 8.`
      ),
    topic: z
      .string()
      .describe(
        'What to compare, taken from the user\'s question — e.g. "GDP by country", "most populous US states", "US electricity generation by source".'
      ),
  }),
};

import type { BarChartData } from "@/features/bar-chart/bar-chart-schema";

const sharedBarChartRequests = new Map<
  string,
  { expiresAt: number; chart: Promise<BarChartData> }
>();
const REUSE_MS = 120_000;

function cacheKey(topic: string, limit: number) {
  return `${topic.trim().toLowerCase()}:${limit}`;
}

function barChartUrl(topic: string, limit: number) {
  const parameters = new URLSearchParams({ limit: String(limit), topic });
  return `/api/bar-chart?${parameters}`;
}

async function fetchBarChart(topic: string, limit: number) {
  const response = await fetch(barChartUrl(topic, limit));
  const body = (await response.json()) as BarChartData | { error: string };
  if (!response.ok || "error" in body) {
    throw new Error(
      "error" in body
        ? body.error
        : `Bar chart request failed: ${response.status}`
    );
  }
  return body;
}

async function requestBarChart(key: string, topic: string, limit: number) {
  try {
    return await fetchBarChart(topic, limit);
  } catch (error) {
    sharedBarChartRequests.delete(key);
    throw error;
  }
}

/**
Load a bar chart's figures. Shared, so the thinking steps and the card make one request between them.
*/
export function loadBarChart(topic: string, limit: number) {
  const key = cacheKey(topic, limit);
  const hit = sharedBarChartRequests.get(key);
  if (hit && Date.now() < hit.expiresAt) {
    return hit.chart;
  }
  const chart = requestBarChart(key, topic, limit);
  sharedBarChartRequests.set(key, {
    chart,
    expiresAt: Date.now() + REUSE_MS,
  });
  return chart;
}

/**
Seed the client cache from a docs recording.
*/
export function primeBarChart(
  topic: string,
  limit: number,
  data: BarChartData
) {
  sharedBarChartRequests.set(cacheKey(topic, limit), {
    chart: Promise.resolve(data),
    expiresAt: Infinity,
  });
}

import { listOf } from "@/features/chat/lookup";
import { loadBarChart } from "@/features/bar-chart/bar-chart-requests";
import { barLimit } from "@/features/bar-chart/bar-chart-schema";
import { hostOf } from "@/lib/url-host";
import type { CardLookup, Source } from "@/features/chat/lookup";

function topicOf(properties: Record<string, unknown>): string {
  return typeof properties.topic === "string" ? properties.topic.trim() : "";
}

function researchSources(result: unknown): readonly Source[] {
  if (!result || typeof result !== "object") {
    return [];
  }
  const { sourceHref, sourceLabel } = result as {
    sourceHref?: unknown;
    sourceLabel?: unknown;
  };
  if (typeof sourceHref !== "string" || !sourceHref) {
    return [];
  }
  const label =
    typeof sourceLabel === "string" && sourceLabel.trim()
      ? sourceLabel.trim()
      : hostOf(sourceHref);
  return [{ href: sourceHref, label }];
}

export const barChartLookup: CardLookup = {
  intent: (topics) =>
    topics.length === 1
      ? `A comparison of ${topics[0]}`
      : `Comparisons of ${listOf(topics)}`,
  load: (properties) => {
    const topic = topicOf(properties);
    return topic
      ? loadBarChart(topic, barLimit(properties.limit))
      : Promise.reject(
          new Error('Pass a topic, for example "GDP by country".')
        );
  },
  resultSources: researchSources,
  sources: () => [
    {
      href: "https://parallel.ai",
      label: "parallel.ai",
    },
  ],
  subject: (properties) => topicOf(properties) || null,
};

import "server-only";
import {
  createExtractTool,
  createSearchTool,
} from "@parallel-web/ai-sdk-tools";
import { generateText, isStepCount, Output } from "ai";
import { barChartResultSchema } from "@/features/bar-chart/bar-chart-schema";
import type {
  BarChartBar,
  BarChartData,
  BarChartResult,
} from "@/features/bar-chart/bar-chart-schema";

/**
Research copies data tables into numbers, so it uses the same model as the area chart's research, separate from the chat model.
*/
const DEFAULT_RESEARCH_MODEL = "anthropic/claude-haiku-5.5";

/**
Tool steps before the model must answer. Step 0 is forced to search and step 1 to extract, so the numbers come from a page rather than memory; without a forced final answer the model keeps digging and returns nothing.
*/
const STEPS = 5;
const TIMEOUT_MS = 55_000;
/**
Parallel serves cached pages by default; an extracted page older than a day is fetched live so a table's newest release isn't missed.
*/
const LIVE_FETCH_MAX_AGE_S = 86_400;

export class BarChartNotFoundError extends Error {
  constructor(topic: string, options?: ErrorOptions) {
    super(`No bar chart figures found for "${topic}".`, options);
    this.name = "BarChartNotFoundError";
  }
}

function researchPrompt(topic: string, limit: number): string {
  const today = new Date();
  const year = today.getUTCFullYear();

  return `Today is ${today.toISOString().slice(0, 10)}. Find real public figures that answer this as a bar chart, one bar per category:

Topic: ${topic}

Requirements:
- Prefer official or well-known statistical sources (World Bank, IMF, OECD, Our World in Data, UN, US Census, US EIA, national stats offices, league or company filings).
- Search first, then extract the best URL(s) — a data table, CSV or JSON API, not an article — and copy the numbers from it.
- Every bar is the same measure for the same period, from one source. Use the latest period that source covers for all categories; it should be ${year - 1} or ${year} for anything still published.
- Up to ${limit} bars. When the topic ranks many categories (countries, states, companies), keep the ${limit} biggest. When it splits one whole into a few parts, keep every part, folding the smallest into "Other" if there are more than ${limit}.
- Leave out totals and aggregates (World, Total, EU) unless the topic asks for them.
- Numeric values only (no units inside the number), in one unit across all bars, written out in full: when a table is in thousands or millions, multiply it out (US$ 30,769,700 million is 30769700000000) and leave "millions" or "thousand" out of the label.
- scale: "percent" for rates/shares, "currency" for money in USD, otherwise "number".
- You have ${STEPS} tool steps, then you must answer from what you extracted.
- If the topic cannot be turned into numbers per category, fail rather than inventing them.`;
}

function cleanBars(
  bars: readonly BarChartBar[],
  limit: number,
  isOrdered: boolean
): BarChartBar[] {
  const byName = new Map<string, number>();
  for (const { name, value } of bars) {
    const trimmed = name.trim();
    if (trimmed && Number.isFinite(value) && !byName.has(trimmed)) {
      byName.set(trimmed, value);
    }
  }
  const cleaned = [...byName].map(([name, value]) => ({ name, value }));
  const sorted = isOrdered
    ? cleaned
    : cleaned.toSorted((left, right) => right.value - left.value);
  return sorted.slice(0, limit);
}

function toBarChartData(
  query: string,
  limit: number,
  output: BarChartResult
): BarChartData {
  const bars = cleanBars(output.bars, limit, output.ordered);
  if (bars.length < 2) {
    throw new BarChartNotFoundError(query);
  }
  return {
    asOf: Date.now(),
    bars,
    fake: false,
    isPartsOfWhole: output.partsOfWhole,
    label: output.label.trim() || "Value",
    period: output.period.trim(),
    scale: output.scale,
    sourceHref: output.sourceHref ?? undefined,
    sourceLabel: output.sourceLabel ?? undefined,
    topic: query,
  };
}

async function researchOnce(
  query: string,
  limit: number,
  abortSignal: AbortSignal
): Promise<BarChartData> {
  const model = process.env.BAR_CHART_MODEL || DEFAULT_RESEARCH_MODEL;
  const webSearch = createSearchTool({
    client_model: model,
    max_results: 8,
    mode: "advanced",
  });
  const webExtract = createExtractTool({
    client_model: model,
    fetch_policy: { max_age_seconds: LIVE_FETCH_MAX_AGE_S },
  });

  const { output } = await generateText({
    abortSignal,
    instructions:
      "You turn questions into honest per-category figures for a generative UI bar chart. Never invent, estimate or recall figures from memory: every value must come from a page you extracted.",
    model,
    output: Output.object({ schema: barChartResultSchema }),
    prepareStep: ({ stepNumber }) => {
      if (stepNumber === 0) {
        return { toolChoice: { toolName: "webSearch", type: "tool" } };
      }
      if (stepNumber === 1) {
        return { toolChoice: { toolName: "webExtract", type: "tool" } };
      }
      return stepNumber >= STEPS ? { toolChoice: "none" } : {};
    },
    prompt: researchPrompt(query, limit),
    stopWhen: isStepCount(STEPS + 1),
    tools: {
      webExtract,
      webSearch,
    },
  });

  if (!output?.bars?.length) {
    throw new BarChartNotFoundError(query);
  }
  return toBarChartData(query, limit, output);
}

async function researchBarChart(
  query: string,
  limit: number
): Promise<BarChartData> {
  const abortSignal = AbortSignal.timeout(TIMEOUT_MS);
  try {
    return await researchOnce(query, limit, abortSignal);
  } catch (error) {
    if (abortSignal.aborted) {
      throw error;
    }
    return await researchOnce(query, limit, abortSignal);
  }
}

/**
Research a free-text topic on the web (Parallel search + extract) and shape it into one bar per category.
*/
export async function getBarChart(
  topic: string,
  limit: number
): Promise<BarChartData> {
  const query = topic.trim();
  if (!query) {
    throw new BarChartNotFoundError(topic);
  }
  if (!process.env.PARALLEL_API_KEY) {
    throw new Error(
      "PARALLEL_API_KEY is missing. Add it to .env.local to load live bar charts."
    );
  }

  try {
    return await researchBarChart(query, limit);
  } catch (error) {
    if (error instanceof BarChartNotFoundError) {
      throw error;
    }
    if (Error.isError(error) && /PARALLEL_API_KEY/u.test(error.message)) {
      throw error;
    }
    throw new BarChartNotFoundError(query, { cause: error });
  }
}

import { z } from "zod";

export const BAR_CHART_SCALES = ["number", "percent", "currency"] as const;
export type BarChartScale = (typeof BAR_CHART_SCALES)[number];

/**
Fewest and most bars the card draws. More than MAX_BARS won't fit the card's height; fewer than MIN_BARS is nothing to compare.
*/
export const MIN_BARS = 2;
export const MAX_BARS = 12;
export const DEFAULT_BARS = 8;

/**
Clamps the model's bar count to what the card can draw; anything unusable means the default.
*/
export function barLimit(value: unknown): number {
  return typeof value !== "number" || !Number.isFinite(value)
    ? DEFAULT_BARS
    : Math.min(Math.max(Math.round(value), MIN_BARS), MAX_BARS);
}

/**
What the model sends: the tool's input.
*/
export const barChartInputSchema = z.object({
  limit: z
    .number()
    .int()
    .min(MIN_BARS)
    .max(MAX_BARS)
    .default(DEFAULT_BARS)
    .describe(
      `How many bars to draw, ${MIN_BARS}–${MAX_BARS}. Use the number the user asks for ("top 5"), otherwise ${DEFAULT_BARS}.`
    ),
  topic: z
    .string()
    .min(1)
    .max(200)
    .describe(
      'What to compare, free text from the user\'s question — e.g. "GDP by country", "most populous US states", "US electricity generation by source".'
    ),
});
export type BarChartInput = z.infer<typeof barChartInputSchema>;

export interface BarChartBar {
  /**
  The category, e.g. "China" or "Solar".
  */
