];

/**
A linear congruential generator (Numerical Recipes' constants) seeded from a string, so a topic always gets the same demo bars. Every product stays under 2^53, so plain arithmetic is exact.
*/
const LCG_MODULUS = 2 ** 32;
const LCG_MULTIPLIER = 1_664_525;
const LCG_INCREMENT = 1_013_904_223;
const SEED_BASE = 31;

function seeded(seed: string) {
  let state = 0;
  for (const char of seed) {
    state = (state * SEED_BASE + (char.codePointAt(0) ?? 0)) % LCG_MODULUS;
  }
  return () => {
    state = (state * LCG_MULTIPLIER + LCG_INCREMENT) % LCG_MODULUS;
    return state / LCG_MODULUS;
  };
}

/**
Demo bars for offline tests. Not used by the live Parallel path.
*/
export function fakeBarChart(
  topic: string,
  limit = DEMO_BARS.length,
  now = Date.UTC(2026, 9, 18, 12, 0)
): BarChartData {
  const query = topic.trim() || "demo comparison";
  const random = seeded(query.toLowerCase());
  const scale = 0.5 + random();
  return {
    asOf: now,
    bars: DEMO_BARS.slice(0, limit).map((bar) => ({
      name: bar.name,
      value: Math.round(bar.value * scale),
    })),
    fake: true,
    isPartsOfWhole: false,
    label: "Value",
    period: "2024",
    scale: "number",
    topic: query,
  };
}

import {
  BarChartNotFoundError,
  getBarChart,
} from "@/features/bar-chart/bar-chart-queries";
import { barLimit } from "@/features/bar-chart/bar-chart-schema";

// Research runs for up to 55s (TIMEOUT_MS).
export const maxDuration = 60;

const CACHE = "public, s-maxage=300, stale-while-revalidate=3600";

// eslint-disable-next-line sonarjs/function-name -- Next.js route handlers must be named after the HTTP method
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const topic = searchParams.get("topic")?.trim() ?? "";

  if (!topic) {
    return Response.json(
      { error: "Pass a topic, for example GDP by country." },
      { status: 400 }
    );
  }

  const requested = searchParams.get("limit");
  const limit = barLimit(requested ? Number(requested) : undefined);
  try {
    const data = await getBarChart(topic, limit);
    return Response.json(data, {
      headers: { "Cache-Control": CACHE },
    });
  } catch (error) {
    const status = error instanceof BarChartNotFoundError ? 404 : 502;
    return Response.json(
      {
        error: Error.isError(error) ? error.message : "Bar chart failed.",
      },
      { status }
    );
  }
}

